#!/usr/bin/env python3
"""Fail when charts/<chart>/VALUES.md (generated by helm-docs) lacks a key that values.yaml has.

Regenerate with deploy/helm/scripts/gen-docs.sh. This gate needs no Docker and no YAML library: it reads the
block-style values.yaml with an indentation stack (the chart files are plain block YAML; lists and empty maps are
leaves, as in helm-docs). Only presence is checked, not description or default; a key counts as documented when its row or an ancestor object's row exists (helm-docs folds a described object into one row).

  python3 deploy/helm/scripts/check-values-docs.py
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
CHARTS = os.path.join(HERE, "..", "charts")
KEY = re.compile(r"^(\s*)([A-Za-z0-9_.\-]+):(.*)$")


def leaf_paths(text):
    rows = []
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        m = KEY.match(line)
        if m:
            rows.append((len(m.group(1)), m.group(2), m.group(3).split(" #")[0].strip(), line.lstrip().startswith("- ")))
        else:
            rows.append((len(line) - len(line.lstrip()), None, None, line.lstrip().startswith("- ")))
    stack, out = [], []
    for i, (ind, key, rest, _) in enumerate(rows):
        if key is None:
            continue
        while stack and stack[-1][0] >= ind:
            stack.pop()
        path = ".".join([k for _, k in stack] + [key])
        nxt = next((r for r in rows[i + 1:]), None)
        is_parent = rest == "" and nxt is not None and nxt[0] > ind and not nxt[3]
        if is_parent:
            stack.append((ind, key))
        else:
            out.append(path)
    return out


def main():
    bad = 0
    for chart in ("vegaduta",):  # core's values use flow-style objects this reader does not unfold
        base = os.path.join(CHARTS, chart)
        with open(os.path.join(base, "values.yaml")) as f:
            keys = leaf_paths(f.read())
        with open(os.path.join(base, "VALUES.md")) as f:
            doc = f.read()
        missing = [k for k in keys if not any("| %s |" % ".".join(k.split(".")[:n]) in doc for n in range(1, len(k.split(".")) + 1))]
        for k in missing:
            print("%s/VALUES.md is missing %s" % (chart, k))
        bad += len(missing)
    if bad:
        print("run deploy/helm/scripts/gen-docs.sh and commit the result")
        return 1
    print("ok: VALUES.md covers every values.yaml key")
    return 0


if __name__ == "__main__":
    sys.exit(main())
